function actionUnitsForTest(actionCount = ['a1']) {
  const markers = Array.isArray(actionCount) && actionCount.length ? actionCount : ['a1'];
  return markers.slice(0, 3).map((marker, index) => ({
    id: `A${index + 1}`,
    action: String(marker || `a${index + 1}`),
    evidence: '(none)',
  }));
}

